<?php require_once '../config/app.php';require_role('admin');$title='Customers';if(isset($_GET['delete'])){stmt($conn,"DELETE FROM users WHERE id=? AND role='customer'",'i',[(int)$_GET['delete']]);flash('Customer deleted.');redirect('customers.php');}$rows=$conn->query("SELECT u.id,u.full_name,u.email,u.created_at,COUNT(DISTINCT v.id) vehicles,COUNT(DISTINCT a.id) appointments FROM users u LEFT JOIN vehicles v ON v.user_id=u.id LEFT JOIN appointments a ON a.user_id=u.id WHERE u.role='customer' GROUP BY u.id ORDER BY u.created_at DESC");include '../includes/admin_header.php';?><div class="toolbar"><input class="search" placeholder="Search customers..." data-search="#customers"><span class="muted">Customer accounts</span></div><div class="table-wrap"><table class="data-table" id="customers"><thead><tr><th>Customer</th><th>Email</th><th>Vehicles</th><th>Appointments</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php if(!$rows->num_rows):?><tr><td colspan="6" class="empty">No customers registered yet.</td></tr><?php else:while($r=$rows->fetch_assoc()):?><tr><td><b><?=e($r['full_name'])?></b></td><td><?=e($r['email'])?></td><td><?=e($r['vehicles'])?></td><td><?=e($r['appointments'])?></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td><td><a class="btn btn-danger btn-sm" data-confirm="Delete this customer and their linked records?" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;endif;?></tbody></table></div><?php include '../includes/footer.php';?>
